// Re-generates the shader table inside packages/compositions/compositions/gl-transition/gl-transition.html from a
// gl-transitions checkout (MIT, https://github.com/gl-transitions/gl-transitions). Scout agent, 2026-10-24.
//
//   bun third_party/gl-transitions/extract.ts <path to a gl-transitions checkout> [commit]
//
// Reads transitions/<file>.glsl for every id in PICK, keeps each file's own Author/License header, and replaces the
// text between the two marker comments in the composition. Fails if a picked file is missing or its licence line is
// not MIT or BSD (the licences BUILD-BRIEF §5g allows).
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, resolve } from "node:path";

/**
 * Our id → upstream file. `cover: true` = its pattern reads with flat colour / transparent inputs (cover, in, out):
 * decided by looking at a cover-mode contact sheet of each (scout, 2026-10-24). `cover: false` ones distort the
 * pictures, and some (burn, cube) paint opaque black when an input is transparent, so the composition refuses them
 * outside images mode. Keep the cover-safe ones first: the manifest's enum order says so.
 */
export const PICK: Array<{ id: string; file: string; cover: boolean }> = [
  { id: "wipe-soft", file: "directionalwipe.glsl", cover: true },
  { id: "circle-open", file: "circleopen.glsl", cover: true },
  { id: "star-wipe", file: "StarWipe.glsl", cover: true },
  { id: "heart", file: "heart.glsl", cover: true },
  { id: "pinwheel", file: "pinwheel.glsl", cover: true },
  { id: "clock-wipe", file: "Radial.glsl", cover: true },
  { id: "window-slice", file: "windowslice.glsl", cover: true },
  { id: "squares-wipe", file: "squareswire.glsl", cover: true },
  { id: "random-squares", file: "randomsquares.glsl", cover: true },
  { id: "polka-dots", file: "PolkaDotsCurtain.glsl", cover: true },
  { id: "melt-bars", file: "DoomScreenTransition.glsl", cover: true },
  { id: "zoom-circles", file: "ZoomInCircles.glsl", cover: true },
  { id: "noise-dissolve", file: "perlin.glsl", cover: true },
  { id: "wind", file: "wind.glsl", cover: true },
  { id: "film-burn", file: "FilmBurn.glsl", cover: true },
  { id: "tv-static", file: "TVStatic.glsl", cover: true },
  { id: "burn", file: "burn.glsl", cover: false },
  { id: "cross-zoom", file: "CrossZoom.glsl", cover: false },
  { id: "cube", file: "cube.glsl", cover: false },
  { id: "pixelize", file: "pixelize.glsl", cover: false },
  { id: "glitch-memories", file: "GlitchMemories.glsl", cover: false },
  { id: "dreamy", file: "Dreamy.glsl", cover: false },
  { id: "cross-warp", file: "crosswarp.glsl", cover: false },
  { id: "ripple", file: "ripple.glsl", cover: false },
  { id: "swirl", file: "Swirl.glsl", cover: false },
  { id: "linear-blur", file: "LinearBlur.glsl", cover: false },
  { id: "water-drop", file: "WaterDrop.glsl", cover: false },
];

const BEGIN = "/* @gl-transitions:begin (generated by third_party/gl-transitions/extract.ts; do not edit by hand) */";
const END = "/* @gl-transitions:end */";

function main(): void {
  const [src, commit = "unknown"] = process.argv.slice(2);
  if (!src) throw new Error("usage: bun third_party/gl-transitions/extract.ts <gl-transitions checkout> [commit]");
  const html = resolve(import.meta.dir, "../../packages/compositions/compositions/gl-transition/gl-transition.html");
  const table: Record<string, { file: string; author: string; license: string; cover: boolean; glsl: string }> = {};
  for (const p of PICK) {
    const path = join(src, "transitions", p.file);
    if (!existsSync(path)) throw new Error(`missing ${path}`);
    const glsl = readFileSync(path, "utf8").replace(/\r\n/g, "\n");
    const author = (glsl.match(/\/\/\s*Author\s*:\s*(.+)/i)?.[1] ?? "unknown").trim();
    const license = (glsl.match(/\/\/\s*License\s*:\s*(.+)/i)?.[1] ?? "").trim();
    if (!/^(MIT|BSD)/i.test(license)) throw new Error(`${p.file}: licence "${license}" is not MIT/BSD`);
    table[p.id] = { file: p.file, author, license, cover: p.cover, glsl };
  }
  const block = `${BEGIN}\nvar GLT_COMMIT = ${JSON.stringify(commit)};\nvar GLT = ${JSON.stringify(table, null, 1)};\n${END}`;
  const text = readFileSync(html, "utf8");
  const a = text.indexOf(BEGIN);
  const b = text.indexOf(END);
  if (a < 0 || b < a) throw new Error("markers not found in gl-transition.html");
  writeFileSync(html, text.slice(0, a) + block + text.slice(b + END.length));
  console.log(`wrote ${Object.keys(table).length} transitions @ ${commit} into ${html}`);
}

main();
